const readInvitation=()=>{const params=new URLSearchParams(window.location.search);return params.getAll('participar').length===1&&/^invite_[a-f0-9]{32}$/.test(params.get('participar'))?params.get('participar'):'';};
const subscribeInvitation=callback=>{window.addEventListener('popstate',callback);return()=>window.removeEventListener('popstate',callback);};
const emptyInvitation=()=>'';
export function ParticipantSelfServicePanel({getSessionToken}){
 const invitationId=useSyncExternalStore(subscribeInvitation,readInvitation,emptyInvitation);
 return invitationId?<ParticipantInvitation key={invitationId} invitationId={invitationId} getSessionToken={getSessionToken}/>:null;
}
function ParticipantInvitation({invitationId,getSessionToken}){
 const api=useParticipantRequest(getSessionToken);
 const [data,setData]=useState(null),[busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[attempt,setAttempt]=useState(null),[canRetry,setCanRetry]=useState(false),alive=useRef(true),sequence=useRef(0);
 useEffect(()=>{alive.current=true;return()=>{alive.current=false;};},[]);
 const confirmed=value=>value.joined===true&&value.saved===true&&typeof value.receiptId==='string'&&Boolean(value.receiptId)&&typeof value.projectId==='string'&&Boolean(value.projectId);
 async function load(){if(busy||!invitationId)return;const current=++sequence.current;setBusy(true);setCanRetry(false);try{const value=await api({invitationId},{},joinEndpoint);if(!alive.current||current!==sequence.current)return;if(value.invitationId!==invitationId||!['INVITED','ACTIVE'].includes(value.state)||value.state==='ACTIVE'&&(!confirmed(value)||value.canAccept!==false)||value.state==='INVITED'&&value.canAccept!==true)throw new Error('No se pudo comprobar esta invitación y su recibo.');setData(value);if(value.state==='ACTIVE'){setAttempt(null);setNotice('Tu participación quedó registrada. Comprobamos el recibo y tu acceso vigente sin repetir la aceptación.');}else if(attempt){setCanRetry(true);setNotice('Todavía no se observa una aceptación confirmada. Podés reenviar explícitamente este mismo intento. No se reenvió automáticamente.');}}catch(error){if(alive.current&&current===sequence.current){setData(null);setNotice(error.message);}}finally{if(alive.current&&current===sequence.current)setBusy(false);}}
 async function accept(){if(busy||!data?.canAccept||attempt&&!canRetry)return;const retrying=Boolean(attempt),current=++sequence.current,command=attempt||{invitationId,operationId:crypto.randomUUID()};setAttempt(command);setBusy(true);setCanRetry(false);try{const value=await api(null,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(command)},joinEndpoint);if(alive.current&&current===sequence.current){if(!confirmed(value))throw new Error('No se confirmó el acceso.');setAttempt(null);setNotice('Tu participación quedó registrada. Actualizá tu cuenta para abrir la obra y presentar tu identidad.');setData(prior=>({...prior,canAccept:false,state:'ACTIVE',receiptId:value.receiptId,projectId:value.projectId}));}}catch(error){if(alive.current&&current===sequence.current){if(!retrying&&!error.retainAttempt&&(error.requestDispatched===false||error.status&&error.status<500))setAttempt(null);if(accessDenied(error))setData(null);setNotice(error.message);}}finally{if(alive.current&&current===sequence.current)setBusy(false);}}
 if(!invitationId)return null;return <section className={styles.panel}><h2>Completar mi invitación de obra</h2><p>Ingresá con el correo invitado, aceptá el enlace de Clerk y seleccioná la organización indicada antes de continuar.</p><p role="status" aria-live="polite">{notice}</p>{!data&&!attempt&&<button type="button" disabled={busy} onClick={load}>Consultar mi invitación</button>}{data&&<><p><strong>{data.organizationName}</strong> · {data.projectName}</p><p>Participante: {data.participantName}. Podés consultar esta obra y presentar tu identidad. La actividad depende de tus permisos y su revisión.</p>{data.state==='ACTIVE'&&<><p className={styles.receipt}>Recibo: {data.receiptId}</p><a href={'/cuenta?'+new URLSearchParams({participar:invitationId,obra:data.projectId}).toString()}>Abrir mi obra en la cuenta</a><button type="button" disabled={busy} onClick={load}>Volver a comprobar mi acceso</button></>}{data.canAccept&&!attempt&&<button type="button" disabled={busy} onClick={accept}>Aceptar participación en esta obra</button>}</>}{attempt&&<><button type="button" disabled={busy} onClick={load}>Comprobar la misma aceptación</button>{canRetry&&<button type="button" disabled={busy} onClick={accept}>Reenviar la misma aceptación</button>}</>}</section>;
}
